    /* ================= V5.1 · 离线图标 / Stage未晋级结果修复 ================= */

    // 1) 国旗完全离线：不再访问 FlagCDN / Wikipedia。
    //    这里用内嵌SVG绘制国家/地区旗帜，浏览器只需要加载当前HTML本身。
    function v51SvgData(svg){return 'data:image/svg+xml;charset=UTF-8,'+encodeURIComponent(svg);}
    function v51FlagSvg(code){
      const c=(code||'').toLowerCase();
      const wrap=body=>`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 30 20">${body}</svg>`;
      const h=(a,b,d)=>wrap(`<rect width="30" height="20" fill="${a}"/><rect y="6.667" width="30" height="6.667" fill="${b}"/><rect y="13.334" width="30" height="6.666" fill="${d}"/>`);
      const v=(a,b,d)=>wrap(`<rect width="30" height="20" fill="${a}"/><rect x="10" width="10" height="20" fill="${b}"/><rect x="20" width="10" height="20" fill="${d}"/>`);
      const nordic=(bg,cross)=>wrap(`<rect width="30" height="20" fill="${bg}"/><rect x="9" width="4" height="20" fill="${cross}"/><rect y="8" width="30" height="4" fill="${cross}"/>`);
      const maps={
        ru:()=>h('#fff','#1747a6','#d52b1e'), de:()=>h('#111','#dd0000','#ffce00'), nl:()=>h('#ae1c28','#fff','#21468b'),
        fr:()=>v('#0055a4','#fff','#ef4135'), be:()=>v('#111','#ffd90c','#ef3340'), pl:()=>wrap('<rect width="30" height="10" fill="#fff"/><rect y="10" width="30" height="10" fill="#dc143c"/>'),
        es:()=>wrap('<rect width="30" height="20" fill="#aa151b"/><rect y="5" width="30" height="10" fill="#f1bf00"/>'),
        pt:()=>wrap('<rect width="30" height="20" fill="#ff0000"/><rect width="12" height="20" fill="#046a38"/><circle cx="12" cy="10" r="3" fill="#ffd100"/>'),
        at:()=>wrap('<rect width="30" height="20" fill="#ed2939"/><rect y="6.667" width="30" height="6.667" fill="#fff"/>'),
        ie:()=>v('#169b62','#fff','#ff883e'),
        sa:()=>wrap('<rect width="30" height="20" fill="#006c35"/><text x="15" y="9" text-anchor="middle" font-family="Arial,sans-serif" font-size="3.3" font-weight="700" fill="#fff">لا إله إلا الله محمد رسول الله</text><path d="M8 14.2h14M20 13.1l2 1.1-2 1.1" stroke="#fff" stroke-width="1" fill="none" stroke-linecap="round" stroke-linejoin="round"/>'),
        dk:()=>nordic('#c8102e','#fff'), fi:()=>nordic('#fff','#003580'), se:()=>nordic('#006aa7','#fecc00'), no:()=>wrap('<rect width="30" height="20" fill="#ba0c2f"/><rect x="8" width="5" height="20" fill="#fff"/><rect y="7.5" width="30" height="5" fill="#fff"/><rect x="9.5" width="2" height="20" fill="#00205b"/><rect y="9" width="30" height="2" fill="#00205b"/>'),
        gb:()=>wrap('<rect width="30" height="20" fill="#012169"/><path d="M0 0L30 20M30 0L0 20" stroke="#fff" stroke-width="4"/><path d="M0 0L30 20M30 0L0 20" stroke="#c8102e" stroke-width="2"/><path d="M15 0V20M0 10H30" stroke="#fff" stroke-width="6"/><path d="M15 0V20M0 10H30" stroke="#c8102e" stroke-width="3"/>'),
        cn:()=>wrap('<rect width="30" height="20" fill="#de2910"/><polygon points="5,3 5.8,5.2 8.2,5.2 6.2,6.6 7,8.8 5,7.5 3,8.8 3.8,6.6 1.8,5.2 4.2,5.2" fill="#ffde00"/>'),
        tw:()=>wrap('<rect width="30" height="20" fill="#fe0000"/><rect width="15" height="10" fill="#000095"/><circle cx="7.5" cy="5" r="2.3" fill="#fff"/><g stroke="#fff" stroke-width=".6"><path d="M7.5 1V9M3.5 5H11.5M4.7 2.2L10.3 7.8M10.3 2.2L4.7 7.8"/></g>'),
        kr:()=>wrap('<rect width="30" height="20" fill="#fff"/><path d="M15 6a4 4 0 1 1 0 8a2 2 0 1 0 0-4a2 2 0 1 1 0-4" fill="#cd2e3a"/><path d="M15 14a4 4 0 1 1 0-8a2 2 0 1 0 0 4a2 2 0 1 1 0 4" fill="#0047a0"/><g stroke="#111" stroke-width="1"><path d="M5 4l5 3M4 6l5 3M20 13l5 3M21 11l5 3M21 4l-5 3M22 6l-5 3M9 13l-5 3M8 11l-5 3"/></g>'),
        jp:()=>wrap('<rect width="30" height="20" fill="#fff"/><circle cx="15" cy="10" r="5" fill="#bc002d"/>'),
        us:()=>wrap('<rect width="30" height="20" fill="#fff"/><g fill="#b22234"><rect width="30" height="1.54"/><rect y="3.08" width="30" height="1.54"/><rect y="6.16" width="30" height="1.54"/><rect y="9.24" width="30" height="1.54"/><rect y="12.32" width="30" height="1.54"/><rect y="15.4" width="30" height="1.54"/><rect y="18.46" width="30" height="1.54"/></g><rect width="13" height="10.8" fill="#3c3b6e"/><g fill="#fff"><circle cx="2" cy="2" r=".45"/><circle cx="5" cy="2" r=".45"/><circle cx="8" cy="2" r=".45"/><circle cx="11" cy="2" r=".45"/><circle cx="3.5" cy="4" r=".45"/><circle cx="6.5" cy="4" r=".45"/><circle cx="9.5" cy="4" r=".45"/><circle cx="2" cy="6" r=".45"/><circle cx="5" cy="6" r=".45"/><circle cx="8" cy="6" r=".45"/><circle cx="11" cy="6" r=".45"/><circle cx="3.5" cy="8" r=".45"/><circle cx="6.5" cy="8" r=".45"/><circle cx="9.5" cy="8" r=".45"/></g>'),
        ca:()=>wrap('<rect width="30" height="20" fill="#fff"/><rect width="6" height="20" fill="#d80621"/><rect x="24" width="6" height="20" fill="#d80621"/><polygon points="15,4 16.2,7.3 18.5,6.4 17.4,9 20,10 16.8,11.2 17.3,14 15,12.6 12.7,14 13.2,11.2 10,10 12.6,9 11.5,6.4 13.8,7.3" fill="#d80621"/>'),
        br:()=>wrap('<rect width="30" height="20" fill="#009c3b"/><polygon points="15,2 27,10 15,18 3,10" fill="#ffdf00"/><circle cx="15" cy="10" r="4.3" fill="#002776"/>'),
        au:()=>wrap('<rect width="30" height="20" fill="#012169"/><rect width="15" height="10" fill="#012169"/><path d="M0 0L15 10M15 0L0 10" stroke="#fff" stroke-width="2"/><path d="M7.5 0V10M0 5H15" stroke="#fff" stroke-width="3"/><path d="M7.5 0V10M0 5H15" stroke="#c8102e" stroke-width="1.5"/><circle cx="23" cy="6" r="1" fill="#fff"/><circle cx="20" cy="14" r="1" fill="#fff"/><circle cx="26" cy="13" r="1" fill="#fff"/>'),
        nz:()=>wrap('<rect width="30" height="20" fill="#012169"/><rect width="15" height="10" fill="#012169"/><path d="M0 0L15 10M15 0L0 10" stroke="#fff" stroke-width="2"/><path d="M7.5 0V10M0 5H15" stroke="#fff" stroke-width="3"/><path d="M7.5 0V10M0 5H15" stroke="#c8102e" stroke-width="1.5"/><g fill="#cc142b" stroke="#fff" stroke-width=".4"><circle cx="21" cy="6" r="1"/><circle cx="25" cy="9" r="1"/><circle cx="20" cy="14" r="1"/><circle cx="26" cy="15" r="1"/></g>'),
        th:()=>wrap('<rect width="30" height="20" fill="#a51931"/><rect y="3" width="30" height="14" fill="#f4f5f8"/><rect y="6" width="30" height="8" fill="#2d2a4a"/>'),
        il:()=>wrap('<rect width="30" height="20" fill="#fff"/><rect y="3" width="30" height="2" fill="#0038b8"/><rect y="15" width="30" height="2" fill="#0038b8"/><polygon points="15,6 18.5,12 11.5,12" fill="none" stroke="#0038b8" stroke-width="1"/><polygon points="15,14 18.5,8 11.5,8" fill="none" stroke="#0038b8" stroke-width="1"/>'),
        lv:()=>wrap('<rect width="30" height="20" fill="#9e3039"/><rect y="8" width="30" height="4" fill="#fff"/>')
      };
      if(maps[c])return maps[c]();
      return wrap(`<rect width="30" height="20" rx="2" fill="#2d3748"/><text x="15" y="13" text-anchor="middle" font-family="Arial,sans-serif" font-size="8" font-weight="700" fill="#fff">${(c||'--').toUpperCase()}</text>`);
    }
    v36FlagMarkup=function(name,isUser=false){
      const code=v36CountryCode(name,isUser);
      if(!code)return '<span class="player-flag user-world" title="自建选手">🌐</span>';
      const upper=code.toUpperCase();
      return `<span class="player-flag" title="${upper}"><img src="${v51SvgData(v51FlagSvg(code))}" alt="${upper}"></span>`;
    };

    // 2) 队徽离线化。能够取得的官方SVG直接内嵌；其余队伍使用本地品牌缩写徽章兜底，绝不再请求Wikipedia。
    const V51_OFFLINE_LOGOS={"ATL":"data:image/svg+xml;base64,","BOS":"data:image/svg+xml;base64,","CDH":"data:image/svg+xml;base64,","DAL":"data:image/svg+xml;base64,","FLA":"data:image/svg+xml;base64,","HZS":"data:image/svg+xml;base64,","HOU":"data:image/svg+xml;base64,","LDN":"data:image/svg+xml;base64,","GLA":"data:image/svg+xml;base64,","VAL":"data:image/svg+xml;base64,","PHI":"data:image/svg+xml;base64,","SEO":"data:image/svg+xml;base64,","SHD":"data:image/svg+xml;base64,","VAN":"data:image/svg+xml;base64,","WAS":"data:image/svg+xml;base64,"};
    const V51_BADGE_ACCENTS={GZC:'#67a2b2',NYXL:'#0f57ea',PAR:'#8d2f3d',SFS:'#fc4c02',TOR:'#c10021',VEG:'#a6192e',INF:'#e6002d'};
    function v51BadgeLogo(short,name){
      const s=(short||'OWL').slice(0,4),accent=V51_BADGE_ACCENTS[s]||'#ff6438';
      const safe=String(name||s).replace(/[<>&]/g,'');
      return v51SvgData(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 96 96"><rect x="4" y="4" width="88" height="88" rx="24" fill="#171b23" stroke="${accent}" stroke-width="6"/><path d="M18 69h60" stroke="${accent}" stroke-width="5" stroke-linecap="round"/><text x="48" y="55" text-anchor="middle" font-family="Arial,sans-serif" font-weight="900" font-size="24" fill="#fff">${s}</text><title>${safe}</title></svg>`);
    }
    function v51OfflineLogoFor(team){
      if(!team)return v51BadgeLogo('OWL','OWL');
      const display=team.displayShort||team.short;
      return V51_OFFLINE_LOGOS[team.short]||v51BadgeLogo(display,team.name);
    }
    function v51ApplyOfflineLogos(){TEAMS.forEach(t=>{t.logo=v51OfflineLogoFor(t);});if(careerState.team)careerState.team.logo=v51OfflineLogoFor(careerState.team);}
    v51ApplyOfflineLogos();
    const _v51ApplySeasonWorldBase=v50ApplySeasonWorld;
    v50ApplySeasonWorld=function(year){const y=_v51ApplySeasonWorldBase(year);v51ApplyOfflineLogos();return y;};
    teamLogoMarkup=function(team,alt=''){
      if(!team)return '<span class="team-logo-fallback" style="display:grid">—</span>';
      const safe=(alt||team.name).replace(/"/g,'&quot;'),abbr=team.displayShort||team.short;
      const src=v51OfflineLogoFor(team);team.logo=src;
      return `<img class="owl-logo-img" src="${src}" alt="${safe}"><span class="team-logo-fallback">${abbr}</span>`;
    };

    // 3) 没有晋级 Stage 季后赛时，也让其他8支队伍把阶段赛完整打完。
    //    玩家结果明确为“未晋级”，同时仍可看到该Stage冠军和亚军，避免undefined。
    skipStageBreak=function(stageNo){
      const table=buildStageTable(stageNo);
      let qualifiers=table.filter(r=>r.qualified).slice(0,8);
      if(qualifiers.length<8){
        const have=new Set(qualifiers.map(r=>r.team.name));
        table.forEach(r=>{if(qualifiers.length<8&&!have.has(r.team.name)&&!r.isUser){qualifiers.push(r);have.add(r.team.name);}});
      }
      qualifiers=qualifiers.slice(0,8).sort((a,b)=>a.rank-b.rank);
      const seeds=qualifiers.map(r=>r.team);
      let champion='待定',runnerUp='待定',finalScore='';
      if(seeds.length>=8){
        const qfPairs=[[0,7],[3,4],[1,6],[2,5]];
        const qf=qfPairs.map(([a,b])=>v42StageSeries(seeds[a],seeds[b],3));
        const sf1=v42StageSeries(qf[0].winner,qf[1].winner,4);
        const sf2=v42StageSeries(qf[2].winner,qf[3].winner,4);
        const final=v42StageSeries(sf1.winner,sf2.winner,4);
        champion=final.winner.name;runnerUp=final.loser.name;finalScore=`${final.scoreA}:${final.scoreB}`;
      }
      const history={stage:stageNo,rank:stageEstimatedRank(stageNo),result:'未晋级',rounds:[],champion,runnerUp,finalScore};
      seasonState.stagePlayoffHistory=seasonState.stagePlayoffHistory||[];
      seasonState.stagePlayoffHistory=seasonState.stagePlayoffHistory.filter(x=>x.stage!==stageNo);
      seasonState.stagePlayoffHistory.push(history);
      seasonState.stageResultSeen=seasonState.stageResultSeen||[];
      seasonState.stageResultSeen=seasonState.stageResultSeen.filter(x=>x!==stageNo);
      seasonState.stageProcessed=seasonState.stageProcessed||[];
      if(!seasonState.stageProcessed.includes(stageNo))seasonState.stageProcessed.push(stageNo);
      seasonState.stageBreakPending=null;
      renderSeason();window.scrollTo({top:0,behavior:'smooth'});
    };

    // 对旧存档中的残缺Stage记录也做显示兜底，避免历史数据继续把undefined带出来。
    v42StageResultCard=function(history){
      const h=history||{};
      const stage=Number.isFinite(Number(h.stage))?Number(h.stage):Math.max(1,Math.min(3,Math.ceil((seasonState.played||7)/7)));
      const result=h.result||'未晋级';
      const champion=h.champion||'阶段冠军待定';
      const runnerUp=h.runnerUp||'阶段亚军待定';
      const playerRounds=(h.rounds||[]).map(r=>`<span class="v42-stage-round ${r.won?'win':'loss'}"><b>${r.round}</b> vs ${r.opponent} · ${r.score||(r.won?'胜':'负')}</span>`).join('');
      let displayFinalScore=h.finalScore||'';if(displayFinalScore){const p=displayFinalScore.split(':').map(Number);if(p.length===2&&p[1]>p[0])displayFinalScore=`${p[1]}:${p[0]}`;}if(displayFinalScore&&displayFinalScore!==h.finalScore)h.finalScore=displayFinalScore;
      const next=stage+1;
      return `<div class="stage-break-card v35-inline-stage v42-stage-result-card">
        <div class="offseason-kicker">STAGE ${stage} PLAYOFFS · FINAL</div>
        <h3>Stage ${stage} 季后赛结束</h3>
        <p>${result==='未晋级'?'你未获得本阶段季后赛资格，但阶段季后赛仍已继续结算。':'阶段季后赛已经全部结算。结果会保留在本赛季记录中。'}</p>
        <div class="stage-break-stats">
          <div><span>你的成绩</span><strong>${result}</strong></div>
          <div><span>冠军</span><strong>${champion}</strong></div>
          <div><span>亚军</span><strong>${runnerUp}</strong></div>
        </div>
        <div class="v42-stage-rounds">${playerRounds||(result==='未晋级'?'<span class="v42-stage-round">本Stage未参加季后赛</span>':'<span class="v42-stage-round">本次未产生玩家对局记录</span>')}</div>
        <div class="v42-stage-final">🏆 总决赛：${champion} ${displayFinalScore} ${runnerUp}</div>
        <button class="primary-btn" id="v42ContinueStageBtn">进入 Stage ${next} →</button>
      </div>`;
    };





